package io.github.miklires.mevents.event;import static org.junit.jupiter.api.Assertions.*;import io.github.miklires.mevents.api.*;import java.util.List;import java.util.random.RandomGenerator;import org.junit.jupiter.api.Test;class EventCoreTest{@Test void lifecycleRejectsSkippingStates(){var machine=new EventStateMachine();assertTrue(machine.canMove(EventState.SCHEDULED,EventState.PREPARING));assertTrue(machine.canMove(EventState.ACTIVE,EventState.COMPLETED));assertFalse(machine.canMove(EventState.SCHEDULED,EventState.ACTIVE));assertThrows(IllegalStateException.class,()->machine.require(EventState.COMPLETED,EventState.ACTIVE));}@Test void selectionUsesWeights(){var a=new RewardDefinition("a",90,List.of()),b=new RewardDefinition("b",10,List.of());var def=new EventDefinition("drop","Drop",EventType.AIRDROP,"world",0,64,0,20,200,"",0,List.of(a,b));assertEquals(a,new RewardSelector(new Fixed(.89)).select(def));assertEquals(b,new RewardSelector(new Fixed(.91)).select(def));}record Fixed(double value)implements RandomGenerator{public long nextLong(){return 0;}public double nextDouble(double bound){return value*bound;}}}
